];

// قراءة الـ PO الحالي
$po_file = __DIR__ . '/rsyi-hr-en_US.po';
$lines   = file( $po_file );
$output  = '';
$msgid   = '';
$in_id   = false;
$in_str  = false;
$filled  = 0;

foreach ( $lines as $line ) {
    $line = rtrim( $line );

    if ( strncmp( $line, 'msgid ', 6 ) === 0 ) {
        $msgid  = stripcslashes( trim( substr( $line, 6 ), '"' ) );
        $in_id  = true;
        $in_str = false;
        $output .= $line . "\n";
        continue;
    }

    if ( strncmp( $line, 'msgstr ', 7 ) === 0 ) {
        $in_id  = false;
        $in_str = true;
        $existing_trans = stripcslashes( trim( substr( $line, 7 ), '"' ) );

        if ( $existing_trans === '' && isset( $translations[ $msgid ] ) ) {
            $output .= 'msgstr "' . addcslashes( $translations[ $msgid ], '"\\' ) . '"' . "\n";
            $filled++;
        } else {
            $output .= $line . "\n";
        }
        continue;
    }

    $output .= $line . "\n";
}

file_put_contents( $po_file, $output );
echo "✓ تم ملء {$filled} ترجمة إنجليزية\n";

// إعادة compile الـ .mo
require_once __DIR__ . '/compile-mo.php';
